102	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
103	     */
104	    @ExceptionHandler(Exception.class)
105	    @ResponseBody
106	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
107	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
108	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
109	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
110	        return ResponseEntity.status(status).body(detail);
111	    }
