205	    @ExceptionHandler(OwnerRegistrationDatePolicy.FutureRegistrationDateException.class)
206	    @ResponseBody
207	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(OwnerRegistrationDatePolicy.FutureRegistrationDateException e, HttpServletRequest request) {
208	        HttpStatus status = HttpStatus.BAD_REQUEST;
