210	        return ResponseEntity.status(status).body(detail);
211	    }
212	
213	    @ExceptionHandler(OwnerDisposableEmailPolicy.DisposableEmailException.class)
214	    @ResponseBody
215	    public ResponseEntity<ProblemDetail> handleDisposableEmailException(OwnerDisposableEmailPolicy.DisposableEmailException e, HttpServletRequest request) {
216	        HttpStatus status = HttpStatus.BAD_REQUEST;
