218	        return ResponseEntity.status(status).body(detail);
219	    }
220	
221	    @ExceptionHandler(MethodArgumentNotValidException.class)
222	    @ResponseBody
223	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
224	        HttpStatus status = HttpStatus.BAD_REQUEST;
225	        BindingErrorsResponse errors = new BindingErrorsResponse();
226	        BindingResult bindingResult = e.getBindingResult();
227	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
228	        if (bindingResult.hasErrors()) {
229	            errors.addAllErrors(bindingResult);
230	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
231	                .map(fieldError -> {
232	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
233	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
234	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
235	                        fieldError.getField(),
236	                        defaultMessage,
237	                        rejectedValue);
238	                    return new ValidationMessageDto(message)
239	                        .putAdditionalProperty("field", fieldError.getField())
240	                        .putAdditionalProperty("rejectedValue", rejectedValue)
241	                        .putAdditionalProperty("defaultMessage", defaultMessage);
242	                })
243	                .toList();
244	            logger.debug("Validation error at {} {}: {}",
245	                request.getMethod(),
246	                request.getRequestURI(),
247	                bindingResult.getFieldErrors());
248	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
249	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
250	                .map(fieldError -> fieldError.getField())
251	                .distinct()
252	                .toList());
253	            return ResponseEntity.status(status).body(detail);
254	        }
255	        return ResponseEntity.status(status).body(detail);
256	    }
